#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
B1 typed topic example.

This demonstrates the newly exposed B1 topic message wrappers plus their typed
subscribers and publishers:
  - ButtonEventMsg / B1ButtonEventSubscriber / B1ButtonEventPublisher
  - RobotStatesMsg / B1RobotStatesSubscriber / B1RobotStatesPublisher
  - ProneBodyControlStatus / B1ProneBodyControlStatusSubscriber / Publisher
  - RobotReplayTrajID / B1RobotReplayTrajIDSubscriber / Publisher
  - RobocupBehaviorStatusMsg / B1RobocupBehaviorStatusSubscriber / Publisher
  - RemoteControllerState / B1RemoteControllerStateSubscriber / Publisher

By default the example publishes to custom loopback topics under
rt/sdk_pybind_b1_topics_example so it does not write to the robot's real state
topics. Use --default-topics with --mode subscribe to listen to the robot's
actual topics.
"""

import argparse
import signal
import sys
import time

try:
    import booster_robotics_sdk_python as br
except ImportError:
    try:
        import _core as br
    except ImportError:
        print("Error: 'booster_robotics_sdk_python' or '_core' module not found.")
        print("Please ensure the SDK is installed or PYTHONPATH is set correctly.")
        sys.exit(1)


BODY_CONTROL_VALUE2NAME = {
    int(br.BodyControl.kUnknown): "kUnknown",
    int(br.BodyControl.kDamping): "kDamping",
    int(br.BodyControl.kPrepare): "kPrepare",
    int(br.BodyControl.kHumanlikeGait): "kHumanlikeGait",
    int(br.BodyControl.kProneBody): "kProneBody",
    int(br.BodyControl.kSoccerGait): "kSoccerGait",
    int(br.BodyControl.kCustom): "kCustom",
    int(br.BodyControl.kGetUp): "kGetUp",
    int(br.BodyControl.kWholeBodyDance): "kWholeBodyDance",
    int(br.BodyControl.kShoot): "kShoot",
    int(br.BodyControl.kInsideFoot): "kInsideFoot",
    int(br.BodyControl.kGoalie): "kGoalie",
    int(br.BodyControl.kWBCGait): "kWBCGait",
    int(br.BodyControl.kLionDancePreparePose): "kLionDancePreparePose",
    int(br.BodyControl.kVisualKickV1): "kVisualKickV1",
}

PRONE_POSTURE_VALUE2NAME = {
    int(br.ProneBodyControlPosture.kUnknown): "kUnknown",
    int(br.ProneBodyControlPosture.kInactive): "kInactive",
    int(br.ProneBodyControlPosture.kPushUp): "kPushUp",
    int(br.ProneBodyControlPosture.kLieDown): "kLieDown",
    int(br.ProneBodyControlPosture.kSoccerLocomotion): "kSoccerLocomotion",
    int(br.ProneBodyControlPosture.kSoccerKicking): "kSoccerKicking",
}

ROBOCUP_BEHAVIOR_STATUS_VALUE2NAME = {
    int(br.RobocupBehaviorStatus.RUNNING): "RUNNING",
    int(br.RobocupBehaviorStatus.SHOOTING): "SHOOTING",
    int(br.RobocupBehaviorStatus.PASSING): "PASSING",
}

REMOTE_EVENT_VALUE2NAME = {
    int(br.RemoteControllerEvent.NONE): "NONE",
    int(br.RemoteControllerEvent.AXIS): "AXIS",
    int(br.RemoteControllerEvent.HAT): "HAT",
    int(br.RemoteControllerEvent.BUTTON_DOWN): "BUTTON_DOWN",
    int(br.RemoteControllerEvent.BUTTON_UP): "BUTTON_UP",
    int(br.RemoteControllerEvent.REMOVE): "REMOVE",
}


def format_value(value, value2name):
    try:
        raw_value = int(value)
    except Exception:
        return str(value)
    name = value2name.get(raw_value)
    if name is None:
        return f"unknown({raw_value})"
    return f"{name}({raw_value})"


def parse_args():
    parser = argparse.ArgumentParser(description="B1 typed topic example")
    parser.add_argument("--domain-id", type=int, default=0)
    parser.add_argument("--iface", type=str, default="")
    parser.add_argument(
        "--mode", choices=("loopback", "subscribe", "publish"),
        default="loopback",
        help="loopback uses custom topics and does publish+subscribe",
    )
    parser.add_argument(
        "--topic-prefix", default="rt/sdk_pybind_b1_topics_example",
        help="prefix used for safe custom loopback topics",
    )
    parser.add_argument(
        "--default-topics", action="store_true",
        help="use SDK default robot topics instead of custom loopback topics",
    )
    parser.add_argument(
        "--allow-publish-default", action="store_true",
        help="allow publishing to SDK default robot topics",
    )
    parser.add_argument(
        "--duration", type=float, default=10.0,
        help="seconds to run; <= 0 means run until Ctrl+C",
    )
    parser.add_argument("--period", type=float, default=1.0)
    return parser.parse_args()


def make_topics(args):
    if args.default_topics:
        return {
            "button": br.kTopicButtonEvent,
            "robot_states": br.kTopicRobotStates,
            "prone_status": br.kTopicProneBodyControlStatus,
            "replay_traj_id": br.kTopicRobotReplayTrajID,
            "robocup_behavior": br.kTopicRobocupBehaviorStatus,
            "remote": br.kTopicRemoteControllerState,
        }

    prefix = args.topic_prefix.rstrip("/")
    return {
        "button": f"{prefix}/button_event",
        "robot_states": f"{prefix}/robot_states",
        "prone_status": f"{prefix}/prone_body_control_status",
        "replay_traj_id": f"{prefix}/robot_replay_traj_id",
        "robocup_behavior": f"{prefix}/robocup_behavior_status",
        "remote": f"{prefix}/remote_controller_state",
    }


def on_button_event(msg):
    print(f"[ButtonEvent] button={msg.button}, event={msg.event}")


def on_robot_states(msg):
    body_control = format_value(
        msg.current_body_control, BODY_CONTROL_VALUE2NAME)
    print(f"[RobotStates] mode={msg.current_mode}, "
          f"body_control={body_control}, actions={list(msg.current_actions)}")


def on_prone_status(msg):
    posture = format_value(msg.posture, PRONE_POSTURE_VALUE2NAME)
    print(f"[ProneBodyControlStatus] posture={posture}")


def on_replay_traj_id(msg):
    print(f"[RobotReplayTrajID] id={msg.id}")


def on_robocup_behavior(msg):
    status = format_value(msg.status, ROBOCUP_BEHAVIOR_STATUS_VALUE2NAME)
    print(f"[RobocupBehaviorStatus] status={status}")


def on_remote_state(msg):
    event = format_value(msg.event, REMOTE_EVENT_VALUE2NAME)
    pressed = [
        name for name in ("a", "b", "x", "y", "lb", "rb", "lt", "rt")
        if getattr(msg, name)
    ]
    print(f"[RemoteControllerState] event={event}, "
          f"axes=({msg.lx:.2f},{msg.ly:.2f},{msg.rx:.2f},{msg.ry:.2f}), "
          f"pressed={pressed}")


def create_subscribers(topics):
    subscriptions = [
        (br.B1ButtonEventSubscriber, on_button_event, topics["button"]),
        (br.B1RobotStatesSubscriber, on_robot_states, topics["robot_states"]),
        (br.B1ProneBodyControlStatusSubscriber,
         on_prone_status, topics["prone_status"]),
        (br.B1RobotReplayTrajIDSubscriber,
         on_replay_traj_id, topics["replay_traj_id"]),
        (br.B1RobocupBehaviorStatusSubscriber,
         on_robocup_behavior, topics["robocup_behavior"]),
        (br.B1RemoteControllerStateSubscriber, on_remote_state, topics["remote"]),
    ]

    subscribers = []
    for subscriber_type, callback, topic in subscriptions:
        sub = subscriber_type(callback, topic)
        sub.InitChannel()
        subscribers.append(sub)
        print(f"Sub: {subscriber_type.__name__} <- {topic}")
    return subscribers


def create_publishers(topics):
    publisher_types = {
        "button": br.B1ButtonEventPublisher,
        "robot_states": br.B1RobotStatesPublisher,
        "prone_status": br.B1ProneBodyControlStatusPublisher,
        "replay_traj_id": br.B1RobotReplayTrajIDPublisher,
        "robocup_behavior": br.B1RobocupBehaviorStatusPublisher,
        "remote": br.B1RemoteControllerStatePublisher,
    }

    publishers = {}
    for key, publisher_type in publisher_types.items():
        pub = publisher_type(topics[key])
        pub.InitChannel()
        publishers[key] = pub
        print(f"Pub: {publisher_type.__name__} -> {topics[key]}")
    return publishers


def publish_sample_messages(publishers, seq):
    button_events = [
        br.ButtonEventType.PRESS_DOWN,
        br.ButtonEventType.PRESS_UP,
        br.ButtonEventType.SINGLE_CLICK,
        br.ButtonEventType.DOUBLE_CLICK,
        br.ButtonEventType.LONG_PRESS_START,
        br.ButtonEventType.LONG_PRESS_END,
    ]
    button = br.ButtonEventMsg()
    button.button = seq % 4
    button.event = button_events[seq % len(button_events)]
    publishers["button"].Write(button)

    robot_states = br.RobotStatesMsg()
    robot_states.current_mode = int(br.RobotMode.kWalking)
    robot_states.current_body_control = int(br.BodyControl.kVisualKickV1)
    robot_states.current_actions = [
        int(br.Action.kRunRecordedTraj),
        int(br.Action.kZeroTorqueDrag),
    ]
    publishers["robot_states"].Write(robot_states)

    postures = [
        br.ProneBodyControlPosture.kSoccerLocomotion,
        br.ProneBodyControlPosture.kSoccerKicking,
    ]
    prone_status = br.ProneBodyControlStatus()
    prone_status.posture = int(postures[seq % len(postures)])
    publishers["prone_status"].Write(prone_status)

    replay_id = br.RobotReplayTrajID()
    replay_id.id = f"example-traj-{seq:03d}"
    publishers["replay_traj_id"].Write(replay_id)

    robocup_statuses = [
        br.RobocupBehaviorStatus.RUNNING,
        br.RobocupBehaviorStatus.SHOOTING,
        br.RobocupBehaviorStatus.PASSING,
    ]
    robocup_status = br.RobocupBehaviorStatusMsg()
    robocup_status.status = int(
        robocup_statuses[seq % len(robocup_statuses)])
    publishers["robocup_behavior"].Write(robocup_status)

    remote_state = br.RemoteControllerState()
    remote_state.event = int(br.RemoteControllerEvent.BUTTON_DOWN)
    remote_state.lx = 0.25
    remote_state.ly = -0.25
    remote_state.rx = 0.10 * (seq % 5)
    remote_state.ry = -0.10 * (seq % 5)
    remote_state.a = (seq % 2 == 0)
    remote_state.b = (seq % 3 == 0)
    remote_state.hat_c = True
    remote_state.reserved = seq % 255
    publishers["remote"].Write(remote_state)


def main():
    args = parse_args()
    if args.default_topics and args.mode in ("loopback", "publish"):
        if not args.allow_publish_default:
            print("Refusing to publish to SDK default robot topics.")
            print("Use --allow-publish-default only when that is intentional.")
            return 2

    br.ChannelFactory.Instance().Init(args.domain_id, args.iface)
    topics = make_topics(args)

    subscribers = []
    publishers = {}
    running = True

    def handle_sigint(sig, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, handle_sigint)

    try:
        if args.mode in ("loopback", "subscribe"):
            subscribers = create_subscribers(topics)

        if args.mode in ("loopback", "publish"):
            publishers = create_publishers(topics)
            time.sleep(0.5)

        seq = 0
        start = time.time()
        print("\nRunning. Press Ctrl+C to exit.\n")
        while running:
            if publishers:
                publish_sample_messages(publishers, seq)
                seq += 1

            if args.duration > 0 and time.time() - start >= args.duration:
                break

            time.sleep(max(args.period, 0.02))

    finally:
        print("\nClosing channels...")
        for sub in subscribers:
            sub.CloseChannel()
        for pub in publishers.values():
            pub.CloseChannel()
        print("Done.")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
